import{_ as e,o as t,a,b as r}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"SIMT编程简介","link":"/api/SIMT-API/SIMT_programming_intro/SIMT_programming_intro"},{"text":"扩展语法","link":"/api/SIMT-API/SIMT_programming_intro/extended_syntax/extended_syntax"},{"text":"内置变量","link":"/api/SIMT-API/SIMT_programming_intro/extended_syntax/builtin_variables"}]},"headers":[],"relativePath":"api/SIMT-API/SIMT_programming_intro/extended_syntax/builtin_variables.md","filePath":"api/SIMT-API/SIMT_programming_intro/extended_syntax/builtin_variables.md","lastUpdated":1787050286000}'),l={name:"api/SIMT-API/SIMT_programming_intro/extended_syntax/builtin_variables.md"};function d(n,i,p,o,_,x){return t(),a("div",null,[...i[0]||(i[0]=[r('<div><article class="markdown-body"><h1>内置变量</h1><p>当前提供了以下仅在Device上可用的dim3类型的内置变量：</p><ul><li><p><a id="blockdim"></a>blockDim</p><p>内置全局变量，在核函数（Kernel）中可以直接使用，用于获取线程块中配置的线程的三维层次结构。blockDim.x，blockDim.y，blockDim.z分别表示线程块中三个维度的线程数。</p></li><li><p><a id="griddim"></a>gridDim</p><p>内置全局变量，只能在核函数（Kernel）中使用，表示整个计算任务在各个维度上分别由多少个线程块构成。</p></li><li><p>blockIdx</p><p>内置全局变量，只能在核函数（Kernel）中使用，用于获取块索引，表示当前线程所在的线程块在整个网格中的位置坐标。</p></li><li><p>threadIdx</p><p>内置全局变量，在核函数（Kernel）中可以直接使用，用于获取当前线程在线程块内部的索引。threadIdx.x，threadIdx.y，threadIdx.z分别表示当前线程在3个维度的索引，threadIdx.x的范围为[0, blockDim.x)，threadIdx.y的范围为[0, blockDim.y)，threadIdx.z的范围为[0, blockDim.z)。线程块内线程的索引计算方式如下：</p><ul><li>对于一维线程块，线程块内线程的索引为threadIdx.x。</li><li>对于二维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x)。</li><li>对于三维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x + threadIdx.z * blockDim.x * blockDim.y)。</li></ul></li></ul><p>当前提供了以下仅在Device上可用的int类型的内置变量：</p><ul><li><p>warpSize</p><p>const int32_t类型变量，表示一个线程束（Warp）中的线程数量，当前为固定值32。</p></li></ul></article></div>',1)])])}const s=e(l,[["render",d]]);export{m as __pageData,s as default};
